package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class CombatBalanceChecks {
 private GameWorld boss(int stage,int level){GameWorld w=new GameWorld();w.level=level;w.evolution=level>=36?2:level>=16?1:0;w.maxHp=w.hp=6+w.evolution*2;w.stage=stage;w.mapIndex=4;w.stageComplete=true;assertTrue(w.advanceStage());w.bossActive=true;w.boss.phase=GameWorld.Phase.PATROL;w.boss.timer=1000;return w;}
 private int hit(GameWorld w,int power,GameWorld.Skill move) throws Exception {java.lang.reflect.Method m=GameWorld.class.getDeclaredMethod("playerHit",GameWorld.Enemy.class,int.class,int.class,GameWorld.Skill.class);m.setAccessible(true);return (Integer)m.invoke(w,w.boss,power,1,move);}
 private void ticks(GameWorld w,int n){for(int i=0;i<n;i++)w.step(1f/60,0,false,false);}
 private GameWorld shooting(GameWorld.Skill move,float y){GameWorld w=new GameWorld();w.enemies.clear();w.spikes.clear();w.invulnerable=100;TestWorlds.equip(w,move);GameWorld.Enemy e=new GameWorld.Enemy(250,y,true);e.hp=e.maxHp=1000;e.timer=1000;w.enemies.add(e);w.setDropSeed(0);return w;}
 @Test public void shortWideAndLongNarrowTradeOff(){assertEquals(220,MoveGeometry.projectileRange(GameWorld.Skill.OVERHEAT),0);assertEquals(200,MoveGeometry.projectileRadius(GameWorld.Skill.OVERHEAT)*2,0);assertEquals(550,MoveGeometry.projectileRange(GameWorld.Skill.DRAGON_PULSE),0);assertEquals(24,MoveGeometry.projectileRadius(GameWorld.Skill.DRAGON_PULSE)*2,0);for(GameWorld.Skill m:GameWorld.Skill.values())if(m.category==GameWorld.Category.SPECIAL){assertTrue(m.name,MoveGeometry.projectileRange(m)<=550);if(MoveGeometry.areaProjectile(m))assertTrue(m.name,MoveGeometry.projectileRange(m)<=320);}}
 @Test public void wideAttackHitsRaisedTargetNarrowAttackMisses(){GameWorld wide=shooting(GameWorld.Skill.HEAT_WAVE,220);assertTrue(wide.trySkill(0));ticks(wide,65);assertTrue(wide.enemies.get(0).hp<1000);GameWorld narrow=shooting(GameWorld.Skill.DRAGON_PULSE,220);assertTrue(narrow.trySkill(0));ticks(narrow,120);assertEquals(1000,narrow.enemies.get(0).hp);}
 @Test public void nonPiercingAreaAttackHitsMultipleEnemies(){GameWorld w=shooting(GameWorld.Skill.FIRE_BLAST,112);GameWorld.Enemy second=new GameWorld.Enemy(250,195,true);second.hp=second.maxHp=1000;second.timer=1000;w.enemies.add(second);w.trySkill(0);ticks(w,55);assertTrue(w.enemies.get(0).hp<1000);assertTrue(second.hp<1000);assertTrue(w.skillShots.isEmpty());}
 @Test public void longShotCannotHitBeyondItsNewRange(){GameWorld w=shooting(GameWorld.Skill.DRAGON_PULSE,112);w.enemies.get(0).x=800;w.trySkill(0);ticks(w,150);assertEquals(1000,w.enemies.get(0).hp);assertTrue(w.skillShots.isEmpty());}
 @Test public void levelsMatchOnSpawnOnLevelUpAndOnRetry(){GameWorld w=new GameWorld();for(GameWorld.Enemy e:w.enemies)assertEquals(w.level,e.level);GameWorld.Enemy injured=w.enemies.get(0);injured.hp=injured.maxHp/2;float fraction=injured.hp/(float)injured.maxHp;w.addExperience(w.xpRequired());for(GameWorld.Enemy e:w.enemies)assertEquals(w.level,e.level);assertEquals(fraction,injured.hp/(float)injured.maxHp,.08);assertTrue(injured.hp<injured.maxHp);while(w.choosingSkill())w.skipLearning();w.stageComplete=true;w.advanceStage();for(GameWorld.Enemy e:w.enemies)assertEquals(w.level,e.level);int entry=w.level;w.addExperience(w.xpRequired());w.hp=0;assertTrue(w.retryStage());assertEquals(entry,w.level);for(GameWorld.Enemy e:w.enemies)assertEquals(w.level,e.level);}
 @Test public void bossesHaveTenTimesHpAndTripleBothDefenses(){for(int stage=1;stage<=3;stage++){GameWorld w=boss(stage,20);assertEquals(w.level,w.boss.level);assertEquals(w.boss.stats().hp*10,w.boss.maxHp);assertEquals(w.boss.stats().defense*3,w.boss.defense(true),0);assertEquals(w.boss.stats().specialDefense*3,w.boss.defense(false),0);}}
 @Test public void bossDamageHasNoPercentCapAndPowerStillMatters() throws Exception {GameWorld w=boss(1,30);int first=hit(w,300,GameWorld.Skill.FOCUS_BLAST);w.boss.hp=w.boss.maxHp;int second=hit(w,600,GameWorld.Skill.FOCUS_BLAST);assertTrue(first>w.boss.maxHp*.04f);assertTrue(second>first*1.8f);assertTrue(w.boss.alive());w.boss.hp=w.boss.maxHp;int before=w.damageAgainst(GameWorld.Skill.FOCUS_BLAST,w.boss);for(int i=0;i<10;i++)w.collectItem(GameWorld.Item.GLASSES);assertTrue(w.damageAgainst(GameWorld.Skill.FOCUS_BLAST,w.boss)>before);}
 @Test public void ordinaryStrongHitsRequireSustainedFight(){for(int stage=1;stage<=3;stage++){GameWorld w=boss(stage,20);GameWorld.Skill move=stage==1?GameWorld.Skill.FOCUS_BLAST:GameWorld.Skill.DIG;int damage=w.damageAgainst(move,w.boss),hits=(w.boss.maxHp+damage-1)/damage;System.out.println("Boss "+stage+" Lv20 HP="+w.boss.maxHp+" damage="+damage+" hits="+hits);assertTrue("hits="+hits,hits>=20&&hits<=65);}}
 @Test public void bossBurnCannotEraseLargeHpPool(){GameWorld w=boss(1,20);w.x=100;w.boss.burnTime=6;w.boss.burnTick=.75f;int hp=w.boss.hp;ticks(w,360);int lost=hp-w.boss.hp;assertTrue(lost>0);assertTrue(lost<=Math.ceil(w.boss.maxHp*.021f));}
}
